using System;using System.Linq;using System.Collections.Generic;using System.Windows.Forms;using System.Threading.Tasks;
namespace GearLab {
 public sealed class TransmissionIntersection {public string First{get;set;}public string Second{get;set;}public double Volume{get;set;}}
 public sealed class TransmissionAuditResult {public bool Complete{get;set;}public int TestedPairs{get;set;}public List<TransmissionIntersection> Pairs{get;set;}}
 public static class TransmissionNativeAudit {
  public static TransmissionAuditResult Run(Result r,double phase,CADKernel kernel){if(Math.Abs(phase)>1e-8&&(r.Wave!=null||r.Train!=null&&r.Train.Stages.Any(n=>n.Parameters.Kind==4)))throw new Exception("Для волновой деформации точная проверка здесь доступна только при нулевой фазе. Динамический контакт не рассчитывается.");var model=new CadAssembly();foreach(var part in r.Model.Parts){var q=new CadPart(part.Id,part.Label,part.Role,part.Color){Placement=part.Placement*PartMotion.Bind(r,part).At(phase,0),Loft=part.Loft,MeshOverride=part.MeshOverride,NativeStep=part.NativeStep};q.Sections.AddRange(part.Sections);model.Parts.Add(q);}return kernel.Run(new CADDocument(),"assembly_audit",null,null,null,new Dictionary<string,object>{{"Spec",TransmissionExport.Spec(model)}}).Audit;}
 }
 public partial class MainForm {
  void InitializeTransmissionTools(){var b=new Button{Text="Пересечения B-rep…",Width=170,Height=32};b.Click+=(s,e)=>AuditTransmission();calculate.Parent.Controls.Add(b);}
  async void AuditTransmission(){if(waveExportBusy||!ReadControls())return;Recalculate();if(!result.Valid||!result.Model.Valid)return;var snapshot=result;double ph=canvas.Phase;canvas.ShowMotion=false;waveExportBusy=true;try{if(waveCancel==null){waveCancel=new Button{Text="Отменить расчёт",Width=135,Height=32};waveCancel.Click+=(s,e)=>waveExportKernel.Cancel();step.Parent.Controls.Add(waveCancel);}waveCancel.Visible=true;footer.Text="Точная проверка общих объёмов в текущей позе…";var audit=await Task.Factory.StartNew(()=>TransmissionNativeAudit.Run(snapshot,ph,waveExportKernel));string report=(audit.Complete?"Проверены все кандидаты":"Достигнут лимит 250 пар; проверка неполная")+". Положительных пересечений: "+audit.Pairs.Count+".\n"+string.Join("\n",audit.Pairs.Take(30).Select(p=>p.First+" ↔ "+p.Second+": "+Engine.F(p.Volume)+" мм³"))+"\nВключены посадки, сборочные контакты и сопряжённые детали; их нужно оценивать по назначению. Проверка относится только к текущей позе, не всему диапазону движения.";notes.Text=report+"\n\n"+notes.Text;tabs.SelectedIndex=2;footer.Text="B-rep проверка завершена.";}catch(Exception ex){footer.Text="Проверка не завершена: "+ex.GetBaseException().Message;}finally{waveExportBusy=false;if(waveCancel!=null)waveCancel.Visible=false;}}
 }
}
